type FaqItem = {
  q: string;
  a: string;
};

type BreadcrumbItem = {
  name: string;
  path: string;
};

type ItemListEntry = {
  name: string;
  path: string;
};

type CreativeWorkOptions = {
  siteUrl: string;
  pagePath: string;
  name: string;
  description?: string;
  inLanguage?: string;
  aboutName?: string;
  sourceUrl?: string;
  isPartOfPath?: string;
  keywords?: string[];
  audienceType?: string;
  genre?: string;
};

type PersonSchemaOptions = {
  siteUrl: string;
  profilePath: string;
  name: string;
  jobTitle?: string;
  description?: string;
  inLanguage?: string;
  sameAs?: string[];
  worksForName?: string;
};

export function buildFAQPageSchema(faqs?: FaqItem[] | null) {
  if (!Array.isArray(faqs) || faqs.length === 0) {
    return undefined;
  }

  const mainEntity = faqs
    .filter((item) => item?.q && item?.a)
    .map((item) => ({
      "@type": "Question",
      name: item.q,
      acceptedAnswer: {
        "@type": "Answer",
        text: item.a,
      },
    }));

  if (mainEntity.length === 0) {
    return undefined;
  }

  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity,
  };
}

function stripTrailingSlash(input: string) {
  return input.replace(/\/+$/, "");
}

function ensureLeadingSlash(input: string) {
  return input.startsWith("/") ? input : `/${input}`;
}

function ensureTrailingSlash(input: string) {
  return input.endsWith("/") ? input : `${input}/`;
}

export function localizeSitePath(
  path: string,
  language: string,
  defaultLanguage: string
) {
  const normalized = ensureTrailingSlash(ensureLeadingSlash(path));

  if (!language || language === defaultLanguage) {
    return normalized;
  }

  return normalized === "/"
    ? `/${language}/`
    : ensureTrailingSlash(`/${language}${normalized}`);
}

export function buildAbsoluteUrl(siteUrl: string, path: string) {
  return `${stripTrailingSlash(siteUrl)}${ensureTrailingSlash(ensureLeadingSlash(path))}`;
}

export function buildBreadcrumbListSchema(
  siteUrl: string,
  items: BreadcrumbItem[]
) {
  if (!siteUrl || !Array.isArray(items) || items.length === 0) {
    return undefined;
  }

  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.name,
      item: buildAbsoluteUrl(siteUrl, item.path),
    })),
  };
}

export function buildItemListSchema(siteUrl: string, items: ItemListEntry[]) {
  if (!siteUrl || !Array.isArray(items) || items.length === 0) {
    return undefined;
  }

  return {
    "@context": "https://schema.org",
    "@type": "ItemList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      url: buildAbsoluteUrl(siteUrl, item.path),
      name: item.name,
    })),
  };
}

export function buildCreativeWorkSchema({
  siteUrl,
  pagePath,
  name,
  description,
  inLanguage,
  aboutName,
  sourceUrl,
  isPartOfPath,
  keywords,
  audienceType,
  genre,
}: CreativeWorkOptions) {
  if (!siteUrl || !pagePath || !name) {
    return undefined;
  }

  const pageUrl = buildAbsoluteUrl(siteUrl, pagePath);
  const cleanKeywords = Array.isArray(keywords)
    ? keywords.map((item) => item.trim()).filter(Boolean)
    : [];

  return {
    "@context": "https://schema.org",
    "@type": "CreativeWork",
    name,
    headline: name,
    url: pageUrl,
    mainEntityOfPage: pageUrl,
    ...(description ? { description, abstract: description } : {}),
    ...(inLanguage ? { inLanguage } : {}),
    ...(genre ? { genre } : {}),
    ...(cleanKeywords.length ? { keywords: cleanKeywords.join(", ") } : {}),
    ...(audienceType
      ? {
          audience: {
            "@type": "Audience",
            audienceType,
          },
        }
      : {}),
    ...(isPartOfPath
      ? {
          isPartOf: {
            "@type": "CollectionPage",
            url: buildAbsoluteUrl(siteUrl, isPartOfPath),
          },
        }
      : {}),
    publisher: {
      "@type": "Organization",
      name: "Code Crafted Studios Inc.",
      url: stripTrailingSlash(siteUrl),
    },
    ...(aboutName
      ? {
          about: {
            "@type": "Organization",
            name: aboutName,
            ...(sourceUrl ? { sameAs: sourceUrl } : {}),
          },
        }
      : {}),
    ...(sourceUrl
      ? {
          mentions: {
            "@type": "WebSite",
            url: sourceUrl,
          },
        }
      : {}),
  };
}

export function buildPersonSchema({
  siteUrl,
  profilePath,
  name,
  jobTitle,
  description,
  inLanguage,
  sameAs,
  worksForName,
}: PersonSchemaOptions) {
  if (!siteUrl || !profilePath || !name) {
    return undefined;
  }

  const profileUrl = buildAbsoluteUrl(siteUrl, profilePath);
  const personId = `${stripTrailingSlash(siteUrl)}/#person`;
  const cleanSameAs = Array.isArray(sameAs)
    ? sameAs.map((item) => item.trim()).filter(Boolean)
    : [];

  return {
    "@context": "https://schema.org",
    "@type": "Person",
    "@id": personId,
    name,
    url: profileUrl,
    ...(jobTitle ? { jobTitle } : {}),
    ...(description ? { description } : {}),
    ...(inLanguage ? { inLanguage } : {}),
    ...(cleanSameAs.length ? { sameAs: cleanSameAs } : {}),
    ...(worksForName
      ? {
          worksFor: {
            "@type": "Organization",
            name: worksForName,
            url: stripTrailingSlash(siteUrl),
          },
        }
      : {}),
  };
}

export function buildProfilePageSchema({
  siteUrl,
  profilePath,
  name,
  description,
  inLanguage,
}: Omit<PersonSchemaOptions, "jobTitle" | "sameAs" | "worksForName">) {
  if (!siteUrl || !profilePath || !name) {
    return undefined;
  }

  const profileUrl = buildAbsoluteUrl(siteUrl, profilePath);
  const personId = `${stripTrailingSlash(siteUrl)}/#person`;

  return {
    "@context": "https://schema.org",
    "@type": "ProfilePage",
    "@id": `${profileUrl}#profile`,
    url: profileUrl,
    name,
    ...(description ? { description } : {}),
    ...(inLanguage ? { inLanguage } : {}),
    mainEntity: {
      "@id": personId,
    },
  };
}
